export function bindingPriority(binding: AlertBinding, context: AlertPolicyContext) {
  const scope = binding.scope;
  if (scope.kind === "protocol") {
    if (scope.proto && scope.proto !== context.proto) return -1;
    if (scope.target && scope.target !== "any" && scope.target !== context.target) return -1;
    return 0;
  }
  if (!context.monitoringTargetIds?.includes(scope.target_id)) return -1;
  return scope.target_type === "group" ? 1 : 2;
}

export function policyTitle(document: AlertsDocument, policyId: string | undefined) {
